/**
 * Machine-author resolution for the #687 PR lifecycle.
 *
 * Whose login counts as "the machine" (the identities the harness authors
 * PRs through) is deployment-specific — this repo never hardcodes it. The
 * knob is a comma-separated LIST of logins since gh-728 (owner directive
 * 2026-10-05: 'ai-teammate,github-actions[bot]' — the CI bot opens its own
 * PRs, live fa PR #1249): `resolveMachineAuthor` returns the raw string;
 * `machineAuthorLogins` splits it; `isMachineAuthored` (authors) and
 * `isMachineLogin` (commit actors) match any entry. All machine-keyed
 * guards (the `notMachine` review rule, the rework re-arm in PR-anchored
 * reviews, the SM `prMachineAuthor` query gate, the sticky-park RESET)
 * resolve through these helpers. Resolution order:
 *
 *   1. `jobParams.machineAuthor` — the JSON parameter at factory setup:
 *      factory-sm.yml `machine-author` input lands in the `dmtools run`
 *      override (`{"params":{"jobParams":{...,"machineAuthor":"..."}}}}`).
 *      The global-level knob: set once by the harness (machine-sm.yml),
 *      valid for every repo the factory runs against.
 *   2. `config.machineAuthor` — the per-repo `.dmtools/config.js` knob,
 *      for fleets where different repos run different bots.
 *   3. `null` — no machine author configured. Every guard keyed on it is
 *      inert/fail-closed per guard: all green PRs are reviewable
 *      (notMachine inert), no `agent:rework` re-arm on verdicts, and the
 *      SM `prMachineAuthor` rules match nothing (no auto legs at all).
 *      Note: `pr_approved` arming on APPROVE is NOT author-gated — the
 *      owner rule auto-approves external PRs too; only auto-REWORK is
 *      machine-only.
 *
 * @param {Object|null} jobParams job params carrying an optional override
 *                                (accepts the sm ctx: it exposes the same
 *                                `machineAuthor` field).
 * @param {Object|null} config    project config (.dmtools/config.js)
 * @returns {string|null} the raw machine-login string (possibly a
 *                        comma-separated list), or null when unconfigured
 */
function resolveMachineAuthor(jobParams, config) {
    if (jobParams && jobParams.machineAuthor) {
        return String(jobParams.machineAuthor);
    }
    if (config && config.machineAuthor) {
        return String(config.machineAuthor);
    }
    return null;
}

/**
 * The raw config string as a LIST of machine logins (gh-728): the knob is
 * a comma-separated string — 'ai-teammate,github-actions[bot]' — and
 * every machine-keyed guard treats it as a SET of logins (a deployment may
 * run several machine identities: the agent harness bot AND the CI bot
 * that opens its own PRs, live fa PR #1249). Trimmed per entry; empty
 * entries dropped; null/absent → the empty list, so every guard keyed on
 * it fails closed exactly like the historical single-login null.
 *
 * @param {string|null} machineAuthor raw resolveMachineAuthor output
 * @returns {string[]} the login entries (possibly empty)
 */
function machineAuthorLogins(machineAuthor) {
    if (!machineAuthor) return [];
    var raw = String(machineAuthor).split(',');
    var out = [];
    for (var i = 0; i < raw.length; i++) {
        var entry = raw[i].trim();
        if (entry) out.push(entry);
    }
    return out;
}

// gh-1025 (live 2026-10-18, SM tick 39103844372): GitHub reports App
// authors WITH a `[bot]` suffix (`dmtools-factory-bot[bot]`) while the
// deployment knob lists the bare login (`dmtools-factory-bot`, added by
// #988 — which therefore never matched). Every prMachineAuthor SM rule
// failed closed for ~8h: zero rework legs, zero arms, queue silently
// dead. Comparisons strip ONE trailing `[bot]` (case-insensitive) from
// both sides; a bare `bot` ending without brackets (`robot`) is never
// touched, and different bots still never match (`dependabot[bot]` !=
// `dmtools-factory-bot`).
function stripBotSuffix(login) {
    return String(login || '').replace(/\[bot\]$/i, '');
}

/**
 * Case-insensitive membership test for ACTOR probes (the sticky-park
 * RESET in smAgent.js): those have always lowercase-compared the head
 * commit's GitHub login against the machine login — with a list, a push
 * by ANY entry is machine movement (the park survives every machine
 * login's push, not just the first one's). The `[bot]` suffix is
 * normalized on both sides (gh-1025).
 *
 * @param {string|null} login      the actor/committer login to test
 * @param {string|null} machineAuthor raw resolveMachineAuthor output
 * @returns {boolean} true when login matches any list entry
 */
function isMachineLogin(login, machineAuthor) {
    var l = stripBotSuffix(String(login || '').toLowerCase());
    if (!l) return false;
    var entries = machineAuthorLogins(machineAuthor);
    for (var i = 0; i < entries.length; i++) {
        if (stripBotSuffix(entries[i].toLowerCase()) === l) return true;
    }
    return false;
}

// Release-bump PRs (the auto-release flow, fa #1093) are authored by the
// REPO OWNER, not by a machine login: `scripts/auto_release.sh` runs in
// CI on main and creates `chore/release-vX.Y.Z` through the owner's
// RELEASE_PAT, so GitHub records the owner as the PR author. The
// deployment knob (`machineAuthor`, e.g. `ai-teammate`) never matches
// them — `prMachineAuthor` rules fired nothing and `notMachine` rules
// kept claiming them, so every release bump stalled outside the machine
// loop (live: fa #1104, 2026-09-30, hand-driven review leg).
//
// Owner rule 2026-09-30: a release-bump PR authored by the REPO OWNER
// counts as machine-authored. Fail-closed everywhere else:
//   - no owner resolvable → false (the shape alone proves nothing);
//   - author != owner → false (a foreigner pushing a chore/release-v*
//     branch is NOT machine — the auto-release flow can only ever author
//     from repo credentials);
//   - anything not matching the bump shape → false.
// The shape: branch `chore/release-v*` (auto_release.sh) OR title
// `chore(release): …` (the squash subject the bump PR carries).
var RELEASE_BUMP_BRANCH_RE = /^chore\/release-v/;
var RELEASE_BUMP_TITLE_RE = /^chore\(release\):/;

// Carrier-field reader: the SM item shape carries author/branch/title
// either flat on the item or on the linked pr payload (both appear in the
// wild — issue-carrier items are flat, prStatus payloads nest under pr).
// Missing everywhere reads as ''.
function itemField(item, field) {
    return String((item && (item[field] || (item.pr && item.pr[field]))) || '');
}

function itemAuthor(item) {
    return itemField(item, 'author');
}

function isMachineReleaseBump(item, owner) {
    var author = itemAuthor(item);
    if (!owner || !author) return false;
    if (author.toLowerCase() !== String(owner).toLowerCase()) return false;
    // The shape: branch `chore/release-v*` (auto_release.sh) OR title
    // `chore(release): …` (the squash subject the bump PR carries).
    return RELEASE_BUMP_BRANCH_RE.test(itemField(item, 'branch')) ||
        RELEASE_BUMP_TITLE_RE.test(itemField(item, 'title'));
}

/**
 * The single machine-authorship predicate for every author-keyed guard
 * (`prMachineAuthor` positive gate, `notMachine` negative filter, the
 * rework re-arms): the deployment's machine logins (the knob is a
 * comma-separated LIST since gh-728 — trim + case-SENSITIVE exact match
 * per entry; PR authors arrive canonicalized from the API) OR a
 * release-bump PR authored by the repo owner (see isMachineReleaseBump).
 * Everything else — including an owner-authored PR with a non-bump
 * shape — is NOT machine. Unconfigured (null/empty knob) → only the
 * release-bump carve-out can match.
 */
function isMachineAuthored(item, machineAuthor, owner) {
    var author = itemAuthor(item);
    if (author) {
        // gh-1025: the bare login part stays case-SENSITIVE (design);
        // only the API's App `[bot]` suffix is normalized away.
        var bareAuthor = stripBotSuffix(author);
        // gh-1025 review: a degenerate '[bot]'-only author strips to ''
        // and must never match ('' === '' would trust everyone).
        if (bareAuthor) {
            var entries = machineAuthorLogins(machineAuthor);
            for (var i = 0; i < entries.length; i++) {
                if (stripBotSuffix(entries[i]) === bareAuthor) return true;
            }
        }
    }
    return isMachineReleaseBump(item, owner);
}

/**
 * Comment/thread-layer trust test (gh-1025 review): the verdict/consume/lap
 * markers and the machine-thread census match comment AUTHORS against the
 * machine allowlist. Same normalization as the login predicates — both
 * sides lowercased and stripped of one trailing `[bot]` — so a marker
 * authored by `dmtools-factory-bot[bot]` (the App identity) is trusted
 * under the bare knob entry `dmtools-factory-bot`. Empty-after-strip never
 * matches; a different bot never matches.
 *
 * @param {string|null} login       comment/thread author login
 * @param {string[]}    loginsList  allowlist entries (machineAuthorLogins output)
 * @returns {boolean}
 */
function loginMatchesList(login, loginsList) {
    var l = stripBotSuffix(String(login || '').toLowerCase());
    if (!l) return false;
    var list = Array.isArray(loginsList) ? loginsList : [];
    for (var i = 0; i < list.length; i++) {
        var e = stripBotSuffix(String(list[i] || '').toLowerCase());
        if (e && e === l) return true;
    }
    return false;
}

module.exports = {
    resolveMachineAuthor: resolveMachineAuthor,
    machineAuthorLogins: machineAuthorLogins,
    isMachineLogin: isMachineLogin,
    isMachineReleaseBump: isMachineReleaseBump,
    isMachineAuthored: isMachineAuthored,
    stripBotSuffix: stripBotSuffix,
    loginMatchesList: loginMatchesList
};

/**
 * Red-verdict convergence (gh-832) — repeated red validation verdicts on an
 * approved head must CONVERGE, never loop dispatch→red→unarm→rearm forever.
 *
 * Live fa PR #1453 (2026-10-10 00:20–08:00Z): 12 dispatch→red→unarm→rearm
 * cycles on an approved head, 5 concluded FAILUREs in a row (the PTY/CLI
 * shard 0/3 flake), zero merges fleet-wide for 3.5h. The existing guards
 * could not stop it: the empty-lap cap and the redHeadSkip arm-side skip
 * are per-head-SHA marker counters — every head refresh resets them, and
 * even when they fire their terminal state is a SILENT log line (no park,
 * no comment). Machine-authored PRs were never parked at all (gh-757 parks
 * guests only) — so a fleet-wide flake in main looped the whole window,
 * and the quarantine PR (#1470) could not merge through it.
 *
 * This module is the pure half of the fix: the consecutive-red streak is
 * DERIVED from the head's own dispatched run history (the durable per-head
 * record, same github_list_workflow_runs list the fail path already fetches
 * for its failed-run link line) — no new markers, no new state carriers:
 *
 *   streakFromRuns(runs, headSha) — trailing count of consecutive concluded
 *      red verdict runs on THIS head (workflow_dispatch only, newest-first).
 *      A 'success' run breaks the streak (gh-832 AC2: a green verdict resets
 *      the counter); 'cancelled' runs are skipped (gh-755 — CANCELLED is
 *      never a verdict, it neither counts nor resets); any other concluded
 *      conclusion (failure/timed_out/…) counts as a red verdict word (sweep
 *      parity). A head change resets the streak by construction — the count
 *      is filtered to the exact head SHA (gh-832 AC2).
 *   parkCapOf(jobParams) — jobParams.redHeadParkCap (default 2): at N
 *      consecutive reds on the unchanged head the fail path parks
 *      validation_failed + a report naming the failing job(s). 0 or
 *      'false' disables the park (deployment escape hatch; the red-head
 *      marker audit trail and the 3-red arm-side skip are unaffected).
 *
 * Pure functions, no tool globals — smAgent wires the transport, tests
 * inject nothing. CommonJS module like every other js/ module. GraalJS
 * rules apply: var + plain functions only.
 */

'use strict';

/**
 * One run participates in THIS head's streak only when it is a
 * workflow_dispatch run of the exact head, already completed. Null entries
 * never participate.
 */
function isHeadDispatchRun(r, headSha) {
    return r && r.event === 'workflow_dispatch' &&
        r.head_sha === headSha && r.status === 'completed';
}

/**
 * The run's recency stamp (REST: updated_at, falling back to created_at,
 * then 0 — the unparsable-stamp run sorts oldest).
 */
function runStampMs(r) {
    return Date.parse(r.updated_at || r.created_at || 0);
}

/** Newest first: the streak reads the TRAILING window of the history. */
function compareRunsNewestFirst(a, b) {
    return runStampMs(b) - runStampMs(a);
}

/**
 * The verdict word of a concluded run: the conclusion as a string, or null
 * when absent/falsy (no verdict word — the run is invisible to the streak).
 */
function concludedVerdictOf(run) {
    return run.conclusion ? String(run.conclusion) : null;
}

/**
 * The head's consecutive concluded-red verdict count, derived from the
 * dispatched-run list (REST shape: [{ event, head_sha, status, conclusion,
 * created_at, updated_at }, …], any order — sorted here newest-first).
 *
 * Walk newest-first over THIS head's workflow_dispatch runs:
 *   completed + conclusion 'success'      → streak ends (green reset, AC2)
 *   completed + conclusion 'cancelled'    → skipped (gh-755: never a verdict)
 *   completed + anything else             → red verdict — streak++
 *   any other status (queued/…)           → ignored (not a verdict)
 * Runs of other heads, other events, and null entries never participate.
 * A null/failed fetch degrades to 0 (fail OPEN: no park on a degraded read —
 * the red-head marker skip still bounds the re-arm arm at 3).
 */
function streakFromRuns(runs, headSha) {
    if (!headSha || !Array.isArray(runs)) return 0;
    var mine = runs.filter(function (r) { return isHeadDispatchRun(r, headSha); });
    mine.sort(compareRunsNewestFirst);
    var streak = 0;
    for (var i = 0; i < mine.length; i++) {
        var c = concludedVerdictOf(mine[i]);
        if (!c || c === 'cancelled') continue;      // gh-755 — no verdict word
        if (c === 'success') break;                 // AC2 — green resets
        streak++;
    }
    return streak;
}

/**
 * The convergence park threshold: how many consecutive red verdicts on an
 * unchanged head park validation_failed. Default 2 (gh-832 AC1: the SECOND
 * consecutive red parks — no third dispatch). jobParams.redHeadParkCap tunes
 * it per deployment; 0 / negative / 'false' disable the park entirely.
 */
function parkCapOf(jobParams) {
    if (String((jobParams || {}).redHeadParkCap) === 'false') return 0;
    var n = (jobParams || {}).redHeadParkCap;
    n = typeof n === 'string' ? parseInt(n, 10) : n;
    if (typeof n !== 'number' || isNaN(n) || n <= 0) return 2;
    return Math.floor(n);
}

/**
 * The park decision at fail time: the CURRENT red is already in the fetched
 * run list, so the streak includes it — park when streak >= cap.
 */
function shouldPark(streak, cap) {
    return cap > 0 && streak >= cap;
}

module.exports = {
    streakFromRuns: streakFromRuns,
    parkCapOf: parkCapOf,
    shouldPark: shouldPark
};

/**
 * Rework in-flight latch (gh-806) — one arming decision per (pr-number,
 * head-sha).
 *
 * Live fa PR #1428 (2026-10-09 04:01–05:04Z): the SM tick logged 9 rework
 * arming decisions for ONE push; 8 legs died silently (dispatch accepted,
 * run never materialized) because rework idempotency lived only in the
 * `agent:rework` label lifecycle and the dispatch-time in-flight-run guards
 * — neither keys the ARMING decision on the PR head. This module is that
 * missing latch:
 *
 *   AC1  while a rework leg for (pr, head) is latched, the tick's armer
 *        logs `⏭️ … rework already in flight for (pr, head)` and dispatches
 *        nothing — `isActive` is the gate every rework arming path consults.
 *   AC2  the latch clears when the leg terminates: a CONCLUDED leg run
 *        (`ai-teammate.yml` workflow) on the latched head that concluded at
 *        or after the arm — success or failure — clears it; a NEW head is a
 *        new key and re-arms normally by construction.
 *   AC3  a latch older than DEFAULT_STALE_MS (45 min) with NO matching
 *        active run is stale and cleared — a leg that never produced a run
 *        is re-armable after a bounded timeout, no human needed.
 *   AC4  lives in the thread fetchers (githubHelpers/scm providers), not
 *        here — resolved threads are filtered before the agent sees them.
 *
 * Persistence: the tick keeps ONE map in memory per pass and rides it into
 * the factory-state snapshot (`state.reworkInFlight`, js/factoryState.js),
 * which the next tick loads back — fa-state.json on the `factory-data`
 * branch is the store, exactly like tick.processed.
 *
 * Pure functions, no tool globals — smAgent wires the transport, tests
 * inject nothing. CommonJS module like every other js/ module. GraalJS
 * rules apply: var + plain functions only.
 */

'use strict';

// gh-806 AC3: N = 45 minutes. A rework leg that produced no run within this
// window is treated as silently dead and the (pr, head) becomes re-armable.
var DEFAULT_STALE_MS = 45 * 60 * 1000;

// The rework/review leg workflow (smAgent dispatches it via workflowRef={branch}).
// Configurable per call so a deployment that renames the workflow stays exact.
var DEFAULT_LEG_WORKFLOW = 'ai-teammate.yml';

var ACTIVE_RUN_STATES = ['queued', 'in_progress', 'waiting', 'pending', 'requested'];

function latchKey(prNumber, headSha) {
    if (prNumber === null || prNumber === undefined || prNumber === '') return null;
    if (!headSha || typeof headSha !== 'string') return null;
    return 'pr-' + prNumber + '@' + headSha;
}

/**
 * Epoch-ms from an epoch number OR an ISO string; null when unparsable.
 */
function toMs(value) {
    if (value === null || value === undefined || value === '') return null;
    if (typeof value === 'number') return isNaN(value) ? null : value;
    var parsed = Date.parse(String(value));
    return isNaN(parsed) ? null : parsed;
}

function nowMsOf(opts) {
    var ms = toMs(opts && opts.now);
    return ms === null ? Date.now() : ms;
}

function staleMsOf(opts) {
    var ms = toMs(opts && opts.staleMs);
    return (ms === null || ms <= 0) ? DEFAULT_STALE_MS : ms;
}

function workflowFileOf(opts) {
    var wf = opts && opts.workflowFile;
    return (wf && typeof wf === 'string') ? wf : DEFAULT_LEG_WORKFLOW;
}

// The raw snapshot payload must be a plain key→entry object — arrays and
// primitives are snapshot drift, never a latch map.
function isRawLatchMap(raw) {
    return !!raw && typeof raw === 'object' && !Array.isArray(raw);
}

// Keys are 'pr-<N>@<head>' — a string carrying the @ separator. (Object.keys
// yields strings; the typeof check stays as the defensive twin of the
// original guard so a weird host never turns a key into a latch.)
function isLatchKey(key) {
    return typeof key === 'string' && key.indexOf('@') !== -1;
}

// The entry itself must be a plain object (arrays are drift).
function isLatchEntryObject(entry) {
    return !!entry && typeof entry === 'object' && !Array.isArray(entry);
}

// A well-formed entry: a non-empty string head (the latch key's other half)
// and an `at` stamp (the stamp may itself be unparsable; isActive then fails
// CLOSED to stale so a corrupt stamp can never latch forever).
function latchEntryValid(entry) {
    return isLatchEntryObject(entry) && !!entry.head &&
        typeof entry.head === 'string' && !!entry.at;
}

// The persisted entry shape: { head, at } (+ by when the armer was named).
function normalizeLatchEntry(entry) {
    var out = { head: entry.head, at: entry.at };
    if (entry.by) out.by = String(entry.by);
    return out;
}

/**
 * Sanitize a persisted latch map (the snapshot's reworkInFlight). Keeps only
 * well-formed entries — 'pr-<N>@<head>' keys with a non-empty head string and
 * an `at` field. Anything else is dropped: the latch must never wedge the
 * armer on snapshot drift.
 */
function normalizeMap(raw) {
    var map = {};
    if (!isRawLatchMap(raw)) return map;
    Object.keys(raw).forEach(function (key) {
        if (!isLatchKey(key) || !latchEntryValid(raw[key])) return;
        map[key] = normalizeLatchEntry(raw[key]);
    });
    return map;
}

/**
 * Record an arming decision for (prNumber, headSha) at `atIso` (default now).
 * No head sha → nothing to key on → no-op (legacy items keep re-arming).
 * Mutates and returns `map` so callers can chain on their own instance.
 */
function arm(map, prNumber, headSha, atIso, by) {
    var key = latchKey(prNumber, headSha);
    if (!key) return map;
    var target = (map && typeof map === 'object') ? map : {};
    target[key] = {
        head: headSha,
        at: atIso || new Date().toISOString()
    };
    if (by) target[key].by = String(by);
    return target;
}

/**
 * Remove the latch for (prNumber, headSha). No-op on unknown keys.
 */
function clear(map, prNumber, headSha) {
    var key = latchKey(prNumber, headSha);
    if (key && map && typeof map === 'object') delete map[key];
    return map;
}

function entryFor(map, prNumber, headSha) {
    var key = latchKey(prNumber, headSha);
    if (!key || !map || typeof map !== 'object') return null;
    var entry = map[key];
    return (entry && typeof entry === 'object') ? entry : null;
}

/**
 * True when the run belongs to the rework/review LEG workflow (path ends
 * with '/<workflowFile>') — the same shape hasActiveLegRun matches in
 * smAgent. Validation CI or kicker runs on the same head must never
 * influence the latch.
 */
function isLegRun(run, workflowFile) {
    if (!run) return false;
    var suffix = '/' + String(workflowFile || DEFAULT_LEG_WORKFLOW);
    var path = String(run.path || '');
    return path.length >= suffix.length &&
        path.slice(path.length - suffix.length) === suffix;
}

function isActiveStatus(status) {
    return ACTIVE_RUN_STATES.indexOf(status) !== -1;
}

/**
 * Does this run keep (active) or resolve (concluded after the arm) a latch
 * for `headSha` set at entryAtMs? Returns 'in-flight', 'terminated' or null.
 * Runs on other heads are ignored — the latch is keyed per head.
 */
function latchEffectOfRun(run, headSha, entryAtMs, workflowFile) {
    if (!isLegRun(run, workflowFile)) return null;
    if (headSha && run.head_sha && String(run.head_sha) !== String(headSha)) return null;
    var status = run.status;
    if (isActiveStatus(status)) return 'in-flight';
    if (status === 'completed') {
        var endedMs = toMs(run.updated_at || run.run_started_at);
        if (endedMs !== null && entryAtMs !== null && endedMs >= entryAtMs) {
            return 'terminated';
        }
    }
    return null;
}

/**
 * Evaluate one entry against the clock and the head's run rollup.
 * Returns the latch cause:
 *   'in-flight'  — fresh latch, or a leg run on the head is still active
 *   'terminated' — a leg run on the head concluded at/after the arm (AC2)
 *   'stale'      — older than staleMs with no matching active run (AC3);
 *                  also the fail-closed answer for an unparsable stamp
 *   'absent'     — no entry
 */
function evaluate(entry, opts) {
    if (!entry) return 'absent';
    var nowMs = nowMsOf(opts);
    var atMs = toMs(entry.at);
    // Unparsable stamp fails CLOSED: treated as stale so a corrupt entry
    // self-heals instead of latching the armer forever.
    if (atMs === null) return 'stale';
    var workflowFile = workflowFileOf(opts);
    var runs = (opts && Array.isArray(opts.runs)) ? opts.runs : null;
    if (runs) {
        for (var i = 0; i < runs.length; i++) {
            var effect = latchEffectOfRun(runs[i], entry.head, atMs, workflowFile);
            if (effect === 'in-flight') return 'in-flight';
            if (effect === 'terminated') return 'terminated';
        }
    }
    if (nowMs - atMs > staleMsOf(opts)) return 'stale';
    return 'in-flight';
}

/**
 * The AC1 gate: is a rework leg in flight for (prNumber, headSha)?
 * Returns { active, cause, entry } — active=true means the armer must log
 * `⏭️ … rework already in flight for (pr, head)` and dispatch nothing.
 * `opts.runs` is the optional head rollup (github_list_workflow_runs shape:
 * {status, conclusion, head_sha, path, updated_at}); a null/absent rollup
 * (failed probe) degrades to age-only evaluation — fail-safe toward
 * suppressing one extra arm, never toward stacking legs.
 */
function isActive(map, prNumber, headSha, opts) {
    var entry = entryFor(map, prNumber, headSha);
    var cause = evaluate(entry, opts);
    return { active: cause === 'in-flight', cause: cause, entry: entry };
}

/**
 * Age-based + run-based sweep for the persisted snapshot: drops entries that
 * are stale (AC3) or whose leg already terminated (AC2). Entries whose leg
 * run is still ACTIVE survive even past the stale window (the leg is really
 * flying — a queued run on a jammed runner must not invite a duplicate).
 * Returns { map, cleared } where cleared lists the dropped keys.
 */
function pruneStale(map, opts) {
    var out = {};
    var cleared = [];
    if (!map || typeof map !== 'object') return { map: out, cleared: cleared };
    Object.keys(map).forEach(function (key) {
        var entry = map[key];
        var cause = evaluate(entry, opts);
        if (cause === 'stale' || cause === 'terminated') {
            cleared.push(key);
        } else {
            out[key] = entry;
        }
    });
    return { map: out, cleared: cleared };
}

/**
 * The arming-storm filter (gh-806 L2): replay N arming decisions against the
 * map — the FIRST decision for a (pr, head) passes and arms the latch, every
 * repeat is suppressed with its cause. Decisions without a head sha never
 * latch and always pass (nothing to key the single-flight on — the dispatch
 * guards stay their only protection, unchanged behavior).
 *
 *   decisions — [{prNumber, headSha}] in tick order
 *   returns   — { allowed, suppressed }; allowed entries are armed into the
 *               map, suppressed entries carry `cause` for the ⏭️ log.
 */
function dedupeArms(map, decisions, opts) {
    var target = (map && typeof map === 'object') ? map : {};
    var allowed = [];
    var suppressed = [];
    (decisions || []).forEach(function (d) {
        var d0 = d || {};
        var verdict = isActive(target, d0.prNumber, d0.headSha, opts);
        if (verdict.active) {
            suppressed.push({
                prNumber: d0.prNumber,
                headSha: d0.headSha,
                cause: verdict.cause
            });
            return;
        }
        arm(target, d0.prNumber, d0.headSha,
            (opts && opts.nowIso) || undefined, (opts && opts.by) || undefined);
        allowed.push({ prNumber: d0.prNumber, headSha: d0.headSha });
    });
    return { allowed: allowed, suppressed: suppressed };
}

module.exports = {
    latchKey: latchKey,
    normalizeMap: normalizeMap,
    arm: arm,
    clear: clear,
    entryFor: entryFor,
    isActive: isActive,
    pruneStale: pruneStale,
    dedupeArms: dedupeArms,
    isLegRun: isLegRun,
    evaluate: evaluate,
    DEFAULT_STALE_MS: DEFAULT_STALE_MS,
    DEFAULT_LEG_WORKFLOW: DEFAULT_LEG_WORKFLOW
};

/**
 * SM Provider — SCM-agnostic I/O for the machine-loop watchdog
 * (machineSmAgent.js).
 *
 * The watchdog's decision core is pure state → actions; this module is the
 * only place that talks to a forge. Provider selection mirrors scm.js:
 *
 *     var provider = createSmProvider({
 *         scm:    { provider: 'github' },           // 'github' | 'gitlab'
 *         repository: { owner: 'epam', repo: 'dmtools-dart' }
 *     });
 *
 * Everything goes through the unified snake_case tool surface (github_* /
 * gitlab_* MCP tools via the dmtools JS bridge) — the same abstraction the
 * rest of the agent ecosystem uses — so the watchdog runs unchanged on any
 * forge the bridge supports. The one exception today is GitHub's
 * update-branch (no native tool yet) which falls back to the gh CLI.
 *
 * Provider contract (all methods):
 *   listMachineIssues(machineLabels, agentHandle, limit) → [{number, title, labels, assignees}]
 *       Open issues carrying any machine label or the agent assignee.
 *   findPr(issueNumber, branchPrefix) → null | {number, state, branch}
 *       OPEN first (branch match <prefix><n> or body references #n), then
 *       MERGED on the branch (close-issue safety net).
 *   prStatus(prNumber) → {state, checkConclusion, mergeState, mergeable, author}
 *       checkConclusion: 'red' | 'green' | 'pending' | 'none'.
 *       author: creator login ('' when the API does not expose it) — the
 *       prMachineAuthor gate keys on it.
 *   activeMachineRuns() → [issueNumber, …]
 *       Issues with a queued/in_progress machine run right now.
 *   dispatchLeg(issueNumber, leg, reason)
 *       Fire the machine runner for that issue (leg: dev/review/rework).
 *   updateBranch(prNumber) / merge(prNumber) / closeIssue(n, comment)
 *   addIssueLabel(issueNumber, label)
 *
 * Known gaps (documented, non-fatal):
 *   - gitlab has no close-issue tool — closeIssue warns and no-ops.
 *   - gitlab activeMachineRuns cannot map a pipeline to an issue number
 *     (pipelines do not expose trigger variables) — any running API-sourced
 *     pipeline counts as "machine busy" (conservative: fewer parallel legs).
 *   - gitlab exposes no machine verdict records (gh-807: no MR-note reader
 *     in the tool catalog yet) — latestVerdictRecord is absent, so the
 *     latestVerdict/notLatestVerdict query guards never match/fail-open and
 *     the reconciliation stays GitHub-machine-loop behavior for now.
 */
'use strict';

// ── Per-tick I/O cache ────────────────────────────────────────────────────
// One TTL cache (60s) for the whole SM tick. Measured on a busy tick: the
// same open-PR list was re-fetched per rule AND per issue findPr (18
// github_list_prs calls returning the same payload in ONE tick). Routing
// the three list sites + prStatus through this cache collapses that to a
// single fetch per kind per repo. TTL hits change nothing observable —
// same payload, same 60s staleness budget as the old per-provider memo
// (the branchHead cache below), now shared across every provider instance
// created during the tick.
//
// runAsync workers are FRESH isolates with an empty module cache: they
// cannot see this holder. createSmProvider({ preseed }) re-hydrates it
// from an args-carried snapshot() bundle — the fan-out in
// sm/sources/githubSource.js ships the snapshot to each worker that way.
var SM_IO_CACHE_TTL_MS = 60 * 1000;
var _cache = { ttlMs: SM_IO_CACHE_TTL_MS, entries: {} };

function ioCacheKey(owner, repo, kind, id) {
    return owner + '/' + repo + ':' + kind + (id ? ':' + id : '');
}

function ioCacheGet(owner, repo, kind, id) {
    var key = ioCacheKey(owner, repo, kind, id);
    var entry = _cache.entries[key];
    if (!entry) return undefined;
    if (Date.now() - entry.at > _cache.ttlMs) {
        delete _cache.entries[key];
        return undefined;
    }
    return entry.data;
}

function ioCachePut(owner, repo, kind, id, data) {
    _cache.entries[ioCacheKey(owner, repo, kind, id)] = { at: Date.now(), data: data };
}

// Drop ONE cached entry (owner directive 2026-10-04 "red yields the slot"):
// the SM tick mutates PR labels mid-tick (fail_validation unarms
// ai_validating) and a LATER rule in the SAME tick must observe the freed
// mutex — validate-armed re-queries the open-PR list, which rides this
// cache. Without the drop the arm rule sees the stale arm and defers the
// whole approved FIFO to the next tick (live fa 2026-10-04 11:0x: #1194
